<?php $title='Staff Performance';require __DIR__.'/includes/header.php';require_admin();$rows=db()->query("SELECT u.id,u.full_name,u.username,COALESCE((SELECT COUNT(*) FROM archives a WHERE a.created_by=u.id),0) archives_added,COALESCE((SELECT COUNT(*) FROM payments p WHERE p.received_by=u.id),0) payments_recorded,COALESCE((SELECT SUM(amount) FROM payments p WHERE p.received_by=u.id),0) total_collected,(SELECT MAX(created_at) FROM activity_logs l WHERE l.user_id=u.id) last_activity FROM users u WHERE u.role='staff' ORDER BY total_collected DESC,archives_added DESC")->fetchAll();?><div class="page-head"><div><h1>Staff Performance</h1><p class="muted">A clear view of archive and payment work by staff.</p></div><a class="btn light" href="activity_log.php">Activity log</a></div><div class="performance-grid"><?php foreach($rows as $i=>$r):?><article class="card performance-card <?=($i===0?'top-performer':'')?>"><div class="performance-rank">#<?=$i+1?></div><h2><?=e($r['full_name'])?></h2><p class="muted">@<?=e($r['username'])?></p><div class="grid grid-2"><div><small class="muted">Archives</small><strong class="metric"><?=e((string)$r['archives_added'])?></strong></div><div><small class="muted">Payments</small><strong class="metric"><?=e((string)$r['payments_recorded'])?></strong></div><div><small class="muted">Collected</small><strong class="metric"><?=CURRENCY.number_format((float)$r['total_collected'],2)?></strong></div><div><small class="muted">Last activity</small><strong class="metric small-metric"><?=e($r['last_activity']?date('M j',strtotime($r['last_activity'])):'—')?></strong></div></div><a class="btn light" href="staff_detail.php?id=<?=$r['id']?>">View details</a></article><?php endforeach;if(!$rows):?><div class="card empty">No staff performance data yet.</div><?php endif;?></div><?php require __DIR__.'/includes/footer.php';
